def test_native_remix_visit_preference_preserves_history_and_playing_clip(tmp_path):
    fixtures={'com/aidj/music/RemixVisitsProbe.java':r'''package com.aidj.music;
import org.json.*;import java.util.*;
public class RemixVisitsProbe {
 static void check(boolean v,String message){if(!v)throw new AssertionError(message);}
 static JSONObject queue(int cap){JSONArray cues=new JSONArray();for(int i=0;i<10;i++)cues.put(new JSONObject().put("start",i*18).put("end",i*18+12).put("bpm",128).put("fade",.2).put("mix",3.2).put("entryVerified",true).put("wordGuarded",true).put("energy",1-i*.05));JSONObject e=new JSONObject().put("id","e").put("trackId","t").put("remixCues",cues);return new JSONObject().put("djEnabled",true).put("djRemix",true).put("currentId","e").put("remixMaxVisits",cap).put("entries",new JSONArray().put(e)).put("tracks",new JSONObject().put("t",new JSONObject().put("duration",240)));}
 static JSONObject e(JSONObject q){return q.getJSONArray("entries").getJSONObject(0);}
 static String key(JSONObject q){JSONObject c=e(q).getJSONObject("dj");return c.getDouble("start")+":"+c.getDouble("end");}
 public static void main(String[] args){
 JSONObject q=queue(3);q.remove("remixMaxVisits");check(RemixPlan.maxVisits(q)==3,"missing preference uses three visits");for(Object[] sample:new Object[][]{{0,1},{100,10},{4.6,5},{"8",3}}){q.put("remixMaxVisits",sample[0]);check(RemixPlan.maxVisits(q)==(Integer)sample[1],"finite numeric preference rounds and clamps; strings use default");}
 for(int cap:new int[]{1,3,10}){q=queue(cap);RemixPlan.arrange(q);Set<String> heard=new HashSet<>();JSONObject song=e(q);int n=0;while(q.getJSONArray("entries").length()>0&&n<12){check(heard.add(key(q)),"higher visit count still selects distinct material");n++;RemixPlan.finish(q,"e","",false);}check(n==cap&&q.getJSONArray("entries").length()==0,"retirement follows the configured visit cap");check(song.getJSONArray("remixUsed").length()==cap,"completed section history retains up to ten signatures");}
 q=queue(3);RemixPlan.arrange(q);String first=key(q);RemixPlan.finish(q,"e","",false);q.put("remixMaxVisits",6);RemixPlan.arrange(q);Set<String> heard=new HashSet<>();heard.add(first);int n=1;while(q.getJSONArray("entries").length()>0&&n<12){check(heard.add(key(q)),"raising the cap never replays earlier sections");n++;RemixPlan.finish(q,"e","",false);}check(n==6,"raising the cap exposes remaining unused variations");
 q=queue(10);RemixPlan.arrange(q);RemixPlan.finish(q,"e","",false);JSONObject playing=e(q).getJSONObject("dj");q.put("remixMaxVisits",1);RemixPlan.arrange(q);check(e(q).getJSONObject("dj")==playing,"lowering the cap cannot cut off the playing section");RemixPlan.finish(q,"e","",false);check(q.getJSONArray("entries").length()==0,"after the playing section the reduced cap retires the song");
 q=queue(3);RemixPlan.arrange(q);RemixPlan.finish(q,"e","",false);JSONObject current=e(q),currentCue=current.getJSONObject("dj"),spent=new JSONObject(current.toString()).put("id","spent"),explicitFull=new JSONObject(current.toString()).put("id","full").put("djFull",true).put("remixVisits",9);q.put("entries",new JSONArray().put(current).put(spent).put(explicitFull)).put("remixMaxVisits",1).put("manualNextId","spent");RemixPlan.arrange(q,"spent");check(q.getJSONArray("entries").length()==2&&e(q)==current&&current.getJSONObject("dj")==currentCue,"arrange retires spent future entries while preserving the already playing section");check(q.getJSONArray("entries").getJSONObject(1).getString("id").equals("full")&&q.getJSONArray("entries").getJSONObject(1).getBoolean("djFull"),"explicit play-full future entry is not removed by the automatic visit cap");check(!q.has("manualNextId"),"manual-next marker for a retired future entry is cleared");
 System.out.println("PROBE_PASSED remix_max_visits default clamp one ten raise lower history unique");
 }
}'''}
    compile_probe(tmp_path,fixtures,['DjPlan.java','PlaybackRange.java','RemixPlan.java'],'RemixVisitsProbe')


def test_native_remix_lookahead_counts_future_songs_and_respects_manual_next(tmp_path):
    fixtures={'com/aidj/music/RemixLookaheadProbe.java':r'''package com.aidj.music;
import org.json.*;
public class RemixLookaheadProbe {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static JSONObject cue(){return new JSONObject().put("start",40).put("end",52).put("bpm",128).put("fade",.2).put("mix",3.2).put("wordGuarded",true).put("entryVerified",true);}
 static JSONObject queue(int depth){JSONObject tracks=new JSONObject();JSONArray entries=new JSONArray();for(int i=0;i<52;i++){String id="t"+i;tracks.put(id,new JSONObject().put("duration",240));JSONObject entry=new JSONObject().put("id","e"+i).put("trackId",id).put("remixCues",new JSONArray().put(cue()));if(i>0&&i<=10)entry.put("djFull",true);entries.put(entry);}return new JSONObject().put("djEnabled",true).put("djRemix",true).put("remixLookahead",depth).put("currentId","e0").put("tracks",tracks).put("entries",entries);}
 static String next(JSONObject q){return q.getJSONArray("entries").getJSONObject(1).getString("id");}
 public static void main(String[] args){
 JSONObject q=queue(1);q.remove("remixLookahead");check(RemixPlan.lookahead(q)==10,"missing lookahead defaults to ten future songs");for(Object[] sample:new Object[][]{{0,1},{99,50},{4.6,5},{"50",10}}){q.put("remixLookahead",sample[0]);check(RemixPlan.lookahead(q)==(Integer)sample[1],"lookahead uses typed finite rounding and bounded depth");}
 q=queue(1);RemixPlan.arrange(q);check(next(q).equals("e1")&&q.getJSONArray("entries").getJSONObject(1).getBoolean("djFull"),"depth one always keeps the immediate successor even if it has no short cue");
 q=queue(10);RemixPlan.arrange(q);check(next(q).equals("e1"),"a matching candidate eleven future songs away is outside a depth-ten search");
 q=queue(50);RemixPlan.arrange(q);check(next(q).equals("e11"),"larger lookahead can select the nearest suitable-tempo snippet beyond ten future songs");
 q=queue(10);q.getJSONArray("entries").getJSONObject(10).remove("djFull");RemixPlan.arrange(q);check(next(q).equals("e10"),"current does not consume one of the ten future candidate slots");
 q=queue(1).put("manualNextId","e51");RemixPlan.arrange(q,"e1");check(next(q).equals("e51"),"explicit manual next overrides both lookahead and an automatic prepared pin");
 System.out.println("PROBE_PASSED remix_lookahead default bounds depth_one ten fifty current_excluded manual_next");
 }
}'''}
    compile_probe(tmp_path,fixtures,['DjPlan.java','PlaybackRange.java','RemixPlan.java'],'RemixLookaheadProbe')


